/**
 * Writes docs/teaching-notes-review.md: every parent teaching note in one
 * file for review. Run: npm run notes:review
 */
import { readFileSync, readdirSync, writeFileSync, mkdirSync } from 'node:fs';
import { resolve } from 'node:path';

const root = resolve(import.meta.dirname, '..');
const dir = resolve(root, 'src/content/teaching-notes');
const names = readdirSync(dir).filter((f) => f.endsWith('.md')).sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));

const out: string[] = [
  '# Parent teaching notes: review sheet',
  '',
  'Generated by `npm run notes:review` from `src/content/teaching-notes/*.md`. Edit the source files, not this sheet.',
  'Each note has six parts: Rule, How to teach, What to say, Common mistakes, Activity, Ready when. Under 150 words each.',
  '',
];
for (const name of names) {
  const md = readFileSync(resolve(dir, name), 'utf8').trim();
  const words = md.split('\n').filter((l) => !l.startsWith('#')).join(' ').split(/\s+/).filter(Boolean).length;
  out.push('---', '', md.replace(/^# /, '## '), '', `_${words} words_`, '');
}
mkdirSync(resolve(root, 'docs'), { recursive: true });
writeFileSync(resolve(root, 'docs/teaching-notes-review.md'), out.join('\n'));
console.log(`wrote docs/teaching-notes-review.md (${names.length} notes)`);
